<?php
/** Read-only diagnostics administration screen. @package NakhostinPerformanceEngine */
namespace Nakhostin\PerformanceEngine\Admin;
use Nakhostin\PerformanceEngine\Core\Capabilities;
use Nakhostin\PerformanceEngine\Infrastructure\Diagnostics;
use Nakhostin\PerformanceEngine\Diagnostics\DiagnosticsExporter;
use Nakhostin\PerformanceEngine\Integrations\LiteSpeed\LiteSpeedGuestVaryProbe;
final class DiagnosticsAdminPage {
	public const SLUG = 'npe-diagnostics';
	public const EXPORT_ACTION = 'npe_export_diagnostics';
	public const GUEST_VARY_ACTION = 'npe_probe_litespeed_guest_vary';
	/** @var Diagnostics */ private $diagnostics; /** @var Capabilities */ private $capabilities; /** @var DiagnosticsExporter */ private $exporter; /** @var LiteSpeedGuestVaryProbe|null */ private $guest_vary;
	public function __construct( Diagnostics $diagnostics, Capabilities $capabilities, ?DiagnosticsExporter $exporter = null, ?LiteSpeedGuestVaryProbe $guest_vary = null ) { $this->diagnostics = $diagnostics; $this->capabilities = $capabilities; $this->exporter = $exporter ?? new DiagnosticsExporter(); $this->guest_vary = $guest_vary; }
	public function register(): void { add_action( 'admin_menu', array( $this, 'add_menu' ) ); add_action( 'admin_post_' . self::EXPORT_ACTION, array( $this, 'export' ) ); add_action( 'admin_post_' . self::GUEST_VARY_ACTION, array( $this, 'probe_guest_vary' ) ); }
	public function probe_guest_vary(): void { if ( ! $this->capabilities->can_manage() || ! $this->guest_vary ) { wp_die( esc_html__( 'You are not allowed to run this diagnostic.', 'nakhostin-performance-engine' ) ); } check_admin_referer( self::GUEST_VARY_ACTION ); $this->guest_vary->probe(); wp_safe_redirect( admin_url( 'admin.php?page=' . self::SLUG ) ); exit; }
	public function export(): void { if ( ! $this->capabilities->can_manage() ) { wp_die( esc_html__( 'You are not allowed to export diagnostics.', 'nakhostin-performance-engine' ) ); } check_admin_referer( self::EXPORT_ACTION ); $payload = $this->exporter->export( $this->diagnostics->report() ); nocache_headers(); header( 'Content-Type: application/json; charset=utf-8' ); header( 'Content-Disposition: attachment; filename="npe-diagnostics.json"' ); echo wp_json_encode( $payload, JSON_PRETTY_PRINT ); exit; }
	public function add_menu(): void { add_submenu_page( AdminPage::SLUG, __( 'Diagnostics', 'nakhostin-performance-engine' ), __( 'Diagnostics', 'nakhostin-performance-engine' ), Capabilities::MANAGE, self::SLUG, array( $this, 'render' ) ); }
	public function render(): void { if ( ! $this->capabilities->can_manage() ) { wp_die( esc_html__( 'You are not allowed to view diagnostics.', 'nakhostin-performance-engine' ) ); } $labels = $this->labels(); ?><div class="wrap npe-admin" dir="<?php echo esc_attr( is_rtl() ? 'rtl' : 'ltr' ); ?>"><h1><?php echo esc_html__( 'Diagnostics', 'nakhostin-performance-engine' ); ?></h1><p><?php echo esc_html__( 'Read-only environment information. No configuration is changed from this screen.', 'nakhostin-performance-engine' ); ?></p><table class="widefat striped"><tbody><?php foreach ( $this->diagnostics->collect() as $key => $value ) : ?><tr><th scope="row"><?php echo esc_html( $labels[ $key ] ?? __( 'Unknown', 'nakhostin-performance-engine' ) ); ?></th><td class="npe-technical" dir="ltr"><?php echo esc_html( is_bool( $value ) ? ( $value ? __( 'Yes', 'nakhostin-performance-engine' ) : __( 'No', 'nakhostin-performance-engine' ) ) : (string) $value ); ?></td></tr><?php endforeach; ?></tbody></table><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="<?php echo esc_attr( self::EXPORT_ACTION ); ?>"><?php wp_nonce_field( self::EXPORT_ACTION ); ?><?php submit_button( __( 'Download sanitized diagnostic report', 'nakhostin-performance-engine' ), 'secondary' ); ?></form><?php if ( $this->guest_vary ) : ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="<?php echo esc_attr( self::GUEST_VARY_ACTION ); ?>"><?php wp_nonce_field( self::GUEST_VARY_ACTION ); ?><?php submit_button( __( 'Run bounded LiteSpeed Guest Vary probe', 'nakhostin-performance-engine' ), 'secondary' ); ?></form><p><?php echo esc_html__( 'This explicit probe has a three-second timeout and never runs for frontend visitors.', 'nakhostin-performance-engine' ); ?></p><?php endif; ?></div><?php }
	private function labels(): array { return array( 'wordpress_version' => __( 'WordPress version', 'nakhostin-performance-engine' ), 'php_version' => __( 'PHP version', 'nakhostin-performance-engine' ), 'server_software' => __( 'Server software', 'nakhostin-performance-engine' ), 'detected_server' => __( 'Detected server platform', 'nakhostin-performance-engine' ), 'reverse_proxy' => __( 'Reverse proxy', 'nakhostin-performance-engine' ), 'wp_cache' => __( 'WP_CACHE enabled', 'nakhostin-performance-engine' ), 'advanced_cache' => __( 'advanced-cache.php detected', 'nakhostin-performance-engine' ), 'object_cache_dropin' => __( 'object-cache.php detected', 'nakhostin-performance-engine' ), 'cache_plugin_active' => __( 'Known page-cache plugin active', 'nakhostin-performance-engine' ), 'gzip_capable' => __( 'Gzip capability', 'nakhostin-performance-engine' ), 'gzip_active' => __( 'Gzip status', 'nakhostin-performance-engine' ), 'brotli_capable' => __( 'Brotli capability', 'nakhostin-performance-engine' ), 'brotli_active' => __( 'Brotli status', 'nakhostin-performance-engine' ), 'https' => __( 'HTTPS', 'nakhostin-performance-engine' ), 'multisite' => __( 'Multisite', 'nakhostin-performance-engine' ), 'woocommerce' => __( 'WooCommerce detected', 'nakhostin-performance-engine' ), 'elementor' => __( 'Elementor detected', 'nakhostin-performance-engine' ), 'litespeed_cache' => __( 'LiteSpeed Cache detected', 'nakhostin-performance-engine' ), 'object_cache' => __( 'External object cache', 'nakhostin-performance-engine' ), 'redis' => __( 'Redis detected', 'nakhostin-performance-engine' ), 'cache_server' => __( 'Cache server platform', 'nakhostin-performance-engine' ), 'cache_page_cache_owner' => __( 'Current page cache owner', 'nakhostin-performance-engine' ), 'cache_ownership_reason' => __( 'Cache ownership reason', 'nakhostin-performance-engine' ), 'cache_available' => __( 'Early cache available', 'nakhostin-performance-engine' ), 'cache_installed' => __( 'NPE early cache installed', 'nakhostin-performance-engine' ), 'cache_dropin_owner' => __( 'advanced-cache.php owner', 'nakhostin-performance-engine' ), 'cache_dropin_reason' => __( 'advanced-cache.php ownership evidence', 'nakhostin-performance-engine' ), 'cache_dropin_replaceable' => __( 'advanced-cache.php safely replaceable', 'nakhostin-performance-engine' ), 'cache_dropin_fingerprint' => __( 'advanced-cache.php diagnostic ID', 'nakhostin-performance-engine' ), 'cache_dropin_bytes' => __( 'advanced-cache.php inspected bytes', 'nakhostin-performance-engine' ), 'cache_filesystem_writable' => __( 'Cache filesystem writable', 'nakhostin-performance-engine' ), 'cache_read_write_healthy' => __( 'Cache entry read/write health', 'nakhostin-performance-engine' ), 'cache_config_present' => __( 'Early cache configuration', 'nakhostin-performance-engine' ), 'cache_object_cache_persistent' => __( 'Persistent object cache', 'nakhostin-performance-engine' ), 'cache_redis_available' => __( 'Redis available', 'nakhostin-performance-engine' ), 'cache_redis_active' => __( 'Redis active', 'nakhostin-performance-engine' ), 'cache_memcached_available' => __( 'Memcached available', 'nakhostin-performance-engine' ), 'cache_litespeed_available' => __( 'LiteSpeed server cache available', 'nakhostin-performance-engine' ), 'cache_conflict' => __( 'Cache ownership conflict', 'nakhostin-performance-engine' ), 'litespeed_guest_vary_state' => __( 'LiteSpeed Guest Vary status', 'nakhostin-performance-engine' ), 'litespeed_guest_vary_http_status' => __( 'LiteSpeed Guest Vary HTTP status', 'nakhostin-performance-engine' ), 'litespeed_guest_vary_duration_ms' => __( 'LiteSpeed Guest Vary duration (ms)', 'nakhostin-performance-engine' ), 'litespeed_guest_vary_message' => __( 'LiteSpeed Guest Vary finding', 'nakhostin-performance-engine' ) ); }
}
